// 1. Validar y normalizar payload de publicación
const input = $input.first().json;
const body = input.body || input;

const workspaceId = body.workspaceId || body.workspace_id;
const brandId = body.brandId || body.brand_id;
const contentId = body.contentId || body.content_id;
const provider = body.provider || 'socialit';
const mode = body.mode || 'dry_run';
const targets = body.targets || [];
const publishPackage = body.publishPackage || body.publish_package || {};

// Aislamiento y validación de campos requeridos
if (!workspaceId) {
  throw new Error('BAD_REQUEST: workspaceId es requerido.');
}
if (!brandId) {
  throw new Error('BAD_REQUEST: brandId es requerido.');
}
if (!contentId) {
  throw new Error('BAD_REQUEST: contentId es requerido.');
}
if (!provider) {
  throw new Error('BAD_REQUEST: provider es requerido.');
}

// GUARDIA ESTRICTA: Solo se acepta mode = 'dry_run' en esta fase
if (mode !== 'dry_run') {
  return [{
    json: {
      error_code: 'REAL_PUBLISHING_DISABLED',
      http_status: 403,
      success: false,
      mode: mode,
      error: 'REAL_PUBLISHING_DISABLED: La publicación real está deshabilitada en esta fase (Kill Switch activo). Solo se admite mode="dry_run".'
    }
  }];
}

if (!Array.isArray(targets) || targets.length === 0) {
  return [{
    json: {
      error_code: 'EMPTY_TARGETS',
      http_status: 400,
      success: false,
      mode: mode,
      error: 'BAD_REQUEST: El array de targets no puede estar vacío.'
    }
  }];
}

return [{
  json: {
    workspaceId,
    brandId,
    contentId,
    provider,
    mode: 'dry_run',
    targets,
    publishPackage,
    is_valid: true
  }
}];

// 2. Expandir dinámicamente targets[] en N items independientes
const input = $input.first().json;

if (!input.is_valid) {
  return [{ json: input }];
}

const { workspaceId, brandId, contentId, provider, mode, targets, publishPackage } = input;

return targets.map(target => ({
  json: {
    workspaceId,
    brandId,
    contentId,
    provider: target.provider || provider,
    mode,
    platform: target.platform,
    connectionId: target.connectionId || target.connection_id || target.id,
    publishPackage,
    is_target_item: true
  }
}));

// 3. Validar individualmente cada target antes de procesar
const items = $input.all();

return items.map(item => {
  const data = item.json;

  if (!data.is_target_item) {
    return { json: data };
  }

  const errors = [];
  if (!data.connectionId) errors.push('connectionId requerido');
  if (!data.platform) errors.push('platform requerida');
  if (!data.workspaceId) errors.push('workspaceId requerido');
  if (!data.brandId) errors.push('brandId requerido');

  const validProviders = ['socialit', 'robin_research', 'meta_direct'];
  if (!validProviders.includes(data.provider)) errors.push(`provider '${data.provider}' no soportado`);

  return {
    json: {
      ...data,
      target_valid: errors.length === 0,
      target_errors: errors
    }
  };
});

// 4. Dry Run Publisher: Simulación determinista sin llamadas a APIs externas
// ZERO PUBLISHING MANDATE: Cero requests a Socialit /v1/posts
const items = $input.all();

return items.map(item => {
  const data = item.json;

  if (!data.is_target_item) {
    return { json: data };
  }

  if (!data.target_valid) {
    return {
      json: {
        success: false,
        mode: 'dry_run',
        published: false,
        platform: data.platform || 'unknown',
        connectionId: data.connectionId || null,
        provider: data.provider,
        would_publish: false,
        errors: data.target_errors
      }
    };
  }

  return {
    json: {
      success: true,
      mode: 'dry_run',
      published: false,
      platform: data.platform,
      connectionId: data.connectionId,
      provider: data.provider,
      would_publish: true,
      target_readiness: {
        has_media: Boolean(data.publishPackage && data.publishPackage.media && data.publishPackage.media.url),
        caption_length: data.publishPackage && data.publishPackage.caption ? data.publishPackage.caption.length : 0,
        hashtags_count: data.publishPackage && Array.isArray(data.publishPackage.hashtags) ? data.publishPackage.hashtags.length : 0
      }
    }
  };
});

// 5. Consolidar Resultados de Publicación Dry Run
const items = $input.all();
const first = items[0] ? items[0].json : {};

// Si hubo error global previo
if (first.error_code) {
  return [{
    json: {
      success: false,
      error_code: first.error_code,
      http_status: first.http_status || 400,
      mode: first.mode || 'dry_run',
      published: false,
      publishing_requests: 0,
      error: first.error,
      timestamp: new Date().toISOString()
    }
  }];
}

const prepData = $('Preparar y Validar Publicación').first().json;

const formattedResults = items.map(item => {
  const d = item.json;
  return {
    platform: d.platform,
    connectionId: d.connectionId,
    provider: d.provider,
    success: d.success === true,
    mode: 'dry_run',
    published: false,
    would_publish: d.would_publish === true,
    target_readiness: d.target_readiness || null
  };
});

const allSuccess = formattedResults.every(r => r.success && r.would_publish);

return [{
  json: {
    success: allSuccess,
    mode: 'dry_run',
    published: false,
    publishing_requests: 0,
    accounts_processed: formattedResults.length,
    contentId: prepData.contentId,
    workspaceId: prepData.workspaceId,
    brandId: prepData.brandId,
    provider: prepData.provider,
    results: formattedResults,
    timestamp: new Date().toISOString()
  }
}];
